+    fn handle_visual_key(&mut self, key: UiKey) -> Vec<UiAction> {
+        match key {
+            UiKey::Esc => {
+                self.clear_visual_selection();
+                self.mode = UiMode::Command;
+            }
+            UiKey::Char('v') => self.set_visual_selection_kind(VisualSelectionKind::Character),
+            UiKey::Char('V') => self.set_visual_selection_kind(VisualSelectionKind::Line),
+            UiKey::Char('\u{16}') => self.set_visual_selection_kind(VisualSelectionKind::Block),
+            UiKey::Char('y') => self.yank_visual_selection(false),
+            UiKey::Char('Y') => self.yank_visual_selection(true),
+            UiKey::Char('h') | UiKey::Left => self.move_visual_column(-1),
+            UiKey::Char('l') | UiKey::Right => self.move_visual_column(1),
+            UiKey::Char('k') | UiKey::Up => self.move_visual_row(-1),
+            UiKey::Char('j') | UiKey::Down => self.move_visual_row(1),
+            _ => {}
+        }
+        Vec::new()
+    }
+
+    fn start_visual_selection(&mut self, kind: VisualSelectionKind) {
+        let pane = if self.focus == PaneFocus::Left && !self.left_visible {
+            PaneFocus::Right
+        } else {
+            self.focus
+        };
+        let lines = self.pane_text_lines(pane);
+        let position = self.current_pane_position(pane, &lines);
+        self.visual_selection = Some(VisualSelection {
+            pane,
+            kind,
+            anchor: position,
+            cursor: position,
+            preferred_column: position.column,
+        });
+        self.mode = UiMode::Command;
+        self.pending = None;
+    }
+
+    fn set_visual_selection_kind(&mut self, kind: VisualSelectionKind) {
+        if let Some(selection) = self.visual_selection.as_mut() {
+            selection.kind = kind;
+        }
+    }
+
+    fn clear_visual_selection(&mut self) {
+        self.visual_selection = None;
+    }
+
+    fn move_visual_row(&mut self, delta: isize) {
+        let Some(pane) = self.visual_selection.as_ref().map(|selection| selection.pane) else {
+            return;
+        };
+        let lines = self.pane_text_lines(pane);
+        let max_row = lines.len().saturating_sub(1);
+        let Some(selection) = self.visual_selection.as_mut() else {
+            return;
+        };
+        let next = (selection.cursor.row as isize + delta).clamp(0, max_row as isize) as usize;
+        selection.cursor.row = next;
+        selection.cursor.column = selection
+            .preferred_column
+            .min(line_cursor_max(lines.get(next).map(String::as_str).unwrap_or("")));
+    }
+
+    fn move_visual_column(&mut self, delta: isize) {
+        let Some(pane) = self.visual_selection.as_ref().map(|selection| selection.pane) else {
+            return;
+        };
+        let lines = self.pane_text_lines(pane);
+        let Some(selection) = self.visual_selection.as_mut() else {
+            return;
+        };
+        let line = lines
+            .get(selection.cursor.row)
+            .map(String::as_str)
+            .unwrap_or("");
+        let max_column = line_cursor_max(line);
+        let next = (selection.cursor.column as isize + delta).clamp(0, max_column as isize) as usize;
+        selection.cursor.column = next;
+        selection.preferred_column = next;
+    }
+
+    fn yank_visual_selection(&mut self, force_line: bool) {
+        let text = self
+            .visual_selection
+            .as_ref()
+            .map(|selection| {
+                let lines = self.pane_text_lines(selection.pane);
+                selected_text(&lines, selection, force_line)
+            })
+            .unwrap_or_default();
+        self.yank_text(text);
+        self.clear_visual_selection();
+        self.mode = UiMode::Command;
+    }
+
+    fn yank_current_line(&mut self) {
+        let pane = if self.focus == PaneFocus::Left && !self.left_visible {
+            PaneFocus::Right
+        } else {
+            self.focus
+        };
+        let lines = self.pane_text_lines(pane);
+        let position = self.current_pane_position(pane, &lines);
+        let text = lines.get(position.row).cloned().unwrap_or_default();
+        self.yank_text(text);
+    }
+
+    fn yank_text(&mut self, text: String) {
+        self.yank_buffer = text;
+        self.pending_clipboard.set(true);
+        self.show_status_notice(
+            format!("yanked {} chars", self.yank_buffer.chars().count()),
+            Duration::from_secs(STATUS_NOTICE_SECONDS),
+        );
+    }
+
+    fn pane_text_lines(&self, pane: PaneFocus) -> Vec<String> {
+        match pane {
+            PaneFocus::Left => self
+                .left_pane_rows()
+                .into_iter()
+                .map(|row| row.text)
+                .collect(),
+            PaneFocus::Right => display_lines(&self.visible_right_content(&self.last_right_content))
+                .into_iter()
+                .map(str::to_string)
+                .collect(),
+        }
+    }
+
+    fn current_pane_position(&self, pane: PaneFocus, lines: &[String]) -> TextPosition {
+        let max_row = lines.len().saturating_sub(1);
+        let row = match pane {
+            PaneFocus::Left => self.control_selected.min(max_row),
+            PaneFocus::Right => max_row,
+        };
+        let column = match pane {
+            PaneFocus::Left => 0,
+            PaneFocus::Right => line_cursor_max(lines.get(row).map(String::as_str).unwrap_or("")),
+        };
+        TextPosition { row, column }
+    }
+
+    fn styled_pane_line(&self, pane: PaneFocus, row: usize, line: &str) -> Spans<'static> {
+        let line_len = line.chars().count();
+        let Some((start, end)) = self
+            .visual_selection
+            .as_ref()
+            .filter(|selection| selection.pane == pane)
+            .and_then(|selection| selection_line_range(selection, row, line_len, false))
+        else {
+            return Spans::from(vec![Span::raw(line.to_string())]);
+        };
+
+        if start >= end {
+            return Spans::from(vec![Span::raw(line.to_string())]);
+        }
+
+        Spans::from(vec![
+            Span::raw(slice_chars(line, 0, start)),
+            Span::styled(
+                slice_chars(line, start, end),
+                Style::default().add_modifier(Modifier::REVERSED),
+            ),
+            Span::raw(slice_chars(line, end, line_len)),
+        ])
+    }
+
+    fn visual_cursor_screen_position(&self) -> Option<(u16, u16)> {
+        let selection = self.visual_selection.as_ref()?;
+        let layout = self.layout();
+        let row = 2_u16.saturating_add(selection.cursor.row.min(usize::from(u16::MAX)) as u16);
+        let column = match selection.pane {
+            PaneFocus::Left => 2_u16.saturating_add(
+                selection.cursor.column.min(usize::from(u16::MAX)) as u16,
+            ),
+            PaneFocus::Right => layout.left_width.saturating_add(2).saturating_add(
+                selection.cursor.column.min(usize::from(u16::MAX)) as u16,
+            ),
+        };
+        Some((row, column))
+    }

